&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience implementing security controls for AI or machine learning platforms.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
