va, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;br&gt;&lt;span style=&quot;font-family: &#39;trebuchet ms&#39;, geneva, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;Join the movement &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;—&lt;/span&gt; &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;apply now!&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt; &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: &#39;trebuchet ms&#39;, geneva, sans-serif; font-size: 12pt;&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:288}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: &#39;trebuchet ms&#39;, geneva, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;What you will do:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;strong&gt;Be the Right Hand:&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;Work closely with the founding and HR-team in their day-to-day operations, ensuring smooth functioning and gaining deep insights into decision-making and startup building processes.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;strong&gt;Actively support the development of our team:&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;Contribute to both strategic and operational tasks related to founding and scaling the organization.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;strong&gt;Organize and manage team events that strengthen team culture and collaboration.&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;Your creativity and organizational skills will help foster a positive and inclusive work environment where team spirit thrives.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;strong&gt;Learning by Doing at the “ALAIKA School”:&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;Engage with professionals across departments, absorbing valuable knowledge, insights, and best practices from within our organisation.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;trebuchet ms&#39;, geneva, sans-serif;&quot;&gt;&lt;strong&gt;Grow &amp;amp; Take Over Responsibility:&lt;/strong&gt;&amp;nbsp;Apply and develop your analytical, interpersonal, creative thinking, technology, and business management skills from day one. Take on increasing responsibility, contributing to both client projects and at least one internal initiative.&lt;/span&gt;&lt;/li&gt;
