&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;9&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Deep experience architecting and operating systems on major cloud platforms (AWS, Azure, and/or GCP)&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;10&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Strong knowledge of cloud-native architecture patterns, including microservices, containers and Kubernetes, serverless, and event-driven design&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;11&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience with infrastructure as code (e.g. Terraform), CI/CD, observability, cloud security and IAM, and cloud cost optimisation (FinOps)&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;12&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Demonstrated ability to lead delivery in multi-team, dependency-heavy environments&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;13&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Strong stakeholder management across Product, Delivery, and Engineering&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;If you are ready to lead engineering delivery at scale, working across complex systems and driving real business outcomes, we encourage you to apply.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:210,&amp;quot;335559739&amp;quot;:210,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We believe the best work happens when we&#39;re together, fostering creativity, collaboration, and connection. That&#39;s why we’ve adopted a hybrid approach, with teams in the office around four days a week. If you require accommodations or flexibility, please discuss this with the hiring team during the interview process.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:210,&amp;quot;335559739&amp;quot;:210,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;WPP is an equal opportunity employer and is committed to fostering a culture of inclusion, respect, and equal opportunity for all.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:210,&amp;quot;335559739&amp;quot;:210,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;We believe the best work happens when we&#39;re together, fostering creativity, collaboration, and connection. That&#39;s why we’ve adopted a hybrid approach, with teams in the office around four days a week. If you require accommodations or flexibility, please discuss this with the hiring team during the interview process.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;WPP is an equal opportunity employer and considers applicants for all positions without discrimination or regard to particular characteristics. We are committed to fostering a culture of respect in which everyone feels they belong and has the same opportunities to progress in their careers.&lt;/strong&gt;&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;Please read our Privacy Notice (&lt;a href=&quot;https://www.wpp.com/en/careers/wpp-privacy-policy-for-recruitment&quot;&gt;https://www.wpp.com/en/careers/wpp-privacy-policy-for-recruitment&lt;/a&gt;) for more information on how we process the information you provide.&lt;/strong&gt;&lt;/h4&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p style=&quot;line-height: 1.5;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt; color: rgb(40, 40, 40);&quot;&gt;About Us&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;Our leading SaaS-based Global Employment Platform™ enables clients to expand into over 180 countries quickly and efficiently, without the complexities of establishing local entities. At G-P, we’re dedicated to breaking down barriers to global business and creating opportunities for everyone, everywhere.&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;Our diverse, remote-first teams are essential to our success. We empower our Dream Team members with flexibility and resources, fostering an environment where innovation thrives and every contribution is valued and celebrated.&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;The work you do here will positively impact lives around the world. We stand by our promise: Opportunity Made Possible. In addition to competitive compensation and benefits, we invite you to join us in expanding your skills and helping to reshape the future of work.&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;At G-P, we assist organizations in building exceptional global teams in days, not months—streamlining the hiring, onboarding, and management process to unlock growth potential for all.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;/p&gt;
&lt;h3 style=&quot;line-height: 1.5;&quot; data-path-to-node=&quot;2&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;About The Position:&lt;/span&gt;&lt;/h3&gt;
&lt;p style=&quot;line-height: 1.5;&quot; data-path-to-node=&quot;3&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;We are seeking an energetic, high-impact &lt;strong data-path-to-node=&quot;3&quot; data-index-in-node=&quot;41&quot;&gt;Talent Acquisition Partner&lt;/strong&gt; to join our global team. This is a full-lifecycle recruiting role requiring a strong balance of execution, candidate engagement, and cross-functional collaboration. You will focus on scaling our &lt;strong data-path-to-node=&quot;5,0&quot; data-index-in-node=&quot;283&quot;&gt;Technical teams (Software Engineering, IT, Product) alongside Go-To-Market (Sales, Revenue, Marketing) and corporate operations&lt;/strong&gt; across international markets. &amp;nbsp;Based in Ireland (or compatible EMEA hours), you will play a key role in connecting with candidates and hiring managers across regions, guiding candidates through complex global offer details and sales compensation structures.&lt;/span&gt;&lt;/p&gt;
&lt;h3 style=&quot;line-height: 1.5;&quot; data-path-to-node=&quot;4&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;What You Will Do:&lt;/span&gt;&lt;/h3&gt;
&lt;ul data-path-to-node=&quot;5&quot;&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt; line-height: 1.5;&quot;&gt;
&lt;p data-path-to-node=&quot;5,0,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;5,0,0&quot; data-index-in-node=&quot;0&quot;&gt;&lt;strong data-path-to-node=&quot;6,0,0&quot; data-index-in-node=&quot;0&quot;&gt;Full-Cycle Execution:&lt;/strong&gt; &lt;/strong&gt;Manage end-to-end recruitment across Technical (Engineering, Product, IT), GTM, and non-tech business functions—from kickoff alignment and targeted sourcing to interviewing, offer negotiations, and pre-onboarding.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt; line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;5,1,0&quot; data-index-in-node=&quot;0&quot;&gt;Sales Comp &amp;amp; Offer Communication:&lt;/strong&gt; Confidently present and explain variable compensation models, including sales incentive plans, commission tiers, and quota structures to revenue-focused candidates.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt; line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;5,2,0&quot; data-index-in-node=&quot;0&quot;&gt;Global Compliance Navigation:&lt;/strong&gt; Work alongside local HR and legal guidelines to ensure offer letters, employment terms, and hiring checks comply with local country regulations.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt; line-height: 1.5;&quot;&gt;
&lt;p data-path-to-node=&quot;5,3,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;5,3,0&quot; data-index-in-node=&quot;0&quot;&gt;Proactive Sourcing:&lt;/strong&gt; Use targeted sourcing techniques to identify and engage qualified passive candidates in competitive SaaS and professional services markets.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt; line-height: 1.5;&quot;&gt;
&lt;p data-path-to-node=&quot;5,4,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;5,4,0&quot; data-index-in-node=&quot;0&quot;&gt;Hiring Manager Partnership:&lt;/strong&gt; Consult with hiring managers to set clear role expectations, refine job descriptions, and keep interview loops moving efficiently.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt; line-height: 1.5;&quot;&gt;
&lt;p data-path-to-node=&quot;5,5,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;5,5,0&quot; data-index-in-node=&quot;0&quot;&gt;Cross-Team Collaboration:&lt;/strong&gt; Partner with HR Operations, Payroll, Compensation, and Finance to ensure seamless process handoffs, budget tracking, and local compliance alignment.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;
&lt;p style=&quot;line-height: 1.5;&quot; data-path-to-node=&quot;5,6,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;5,6,0&quot; data-index-in-node=&quot;0&quot;&gt;Pipeline Tracking:&lt;/strong&gt; Maintain real-time ATS hygiene to give leadership visibility into pipeline health and recruiting metrics.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 style=&quot;line-height: 1.5;&quot; data-path-to-node=&quot;6&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;What We Are Looking For:&lt;/span&gt;&lt;/h3&gt;
&lt;h4 style=&quot;line-height: 1.5;&quot; data-path-to-node=&quot;7&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;Minimum Requirements:&lt;/span&gt;&lt;/h4&gt;
&lt;ul data-path-to-node=&quot;8&quot;&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;
&lt;p data-path-to-node=&quot;8,0,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;8,0,0&quot; data-index-in-node=&quot;0&quot;&gt;3+ years of full-lifecycle recruiting experience&lt;/strong&gt;, with a focus on both Technical and non-technical roles including AI/Software Engineering Product GTM/Sales, Marketing, or corporate functions (HR Ops, Payroll, Finance).&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;
&lt;p data-path-to-node=&quot;8,1,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;8,1,0&quot; data-index-in-node=&quot;0&quot;&gt;Location &amp;amp; Time Zone:&lt;/strong&gt; Based in Ireland (or compatible EMEA hours) to align with global stakeholders and candidate pipelines.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;
&lt;p data-path-to-node=&quot;8,2,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;8,2,0&quot; data-index-in-node=&quot;0&quot;&gt;Sales Incentive Familiarity:&lt;/strong&gt; Demonstrated ability to clearly walk sales and revenue candidates through variable incentive, OTE, and commission plan mechanics.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;6,2,0&quot; data-index-in-node=&quot;0&quot;&gt;Technical Recruiting Proficiency:&lt;/strong&gt; Demonstrated capability to source, screen, and engage specialized engineering talent alongside core business functions.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;
&lt;p data-path-to-node=&quot;8,3,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;8,3,0&quot; data-index-in-node=&quot;0&quot;&gt;Global Hiring Exposure:&lt;/strong&gt; Direct experience navigating cross-border hiring, international employment considerations, and local compliance checks.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 style=&quot;line-height: 1.5;&quot; data-path-to-node=&quot;9&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;Preferred Requirements:&lt;/span&gt;&lt;/h4&gt;
&lt;ul data-path-to-node=&quot;10&quot;&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt; line-height: 1.5;&quot;&gt;
&lt;p data-path-to-node=&quot;10,0,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;Experience working within a fast-paced global SaaS, Tech, or Professional Services environment.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt; line-height: 1.5;&quot;&gt;
&lt;p data-path-to-node=&quot;10,1,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;Hands-on proficiency with modern recruiting tools and ATS platforms (&lt;strong data-path-to-node=&quot;10,1,0&quot; data-index-in-node=&quot;69&quot;&gt;Greenhouse&lt;/strong&gt; strongly preferred).&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;
&lt;p style=&quot;line-height: 1.5;&quot; data-path-to-node=&quot;10,2,0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;Proven capability in advanced sourcing methodologies (Boolean, targeted market mapping) for niche or international markets.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div id=&quot;message-list_1761669766.039629&quot; class=&quot;c-virtual_list__item&quot; data-qa=&quot;virtual-list-item&quot; data-item-key=&quot;1761669766.039629&quot;&gt;
&lt;div class=&quot;c-message_kit__background c-message_kit__background--hovered p-message_pane_message__message c-message_kit__message&quot; data-qa=&quot;message_container&quot; data-qa-unprocessed=&quot;false&quot; data-qa-placeholder=&quot;false&quot;&gt;
&lt;div class=&quot;c-message_kit__hover c-message_kit__hover--hovered&quot; data-qa-hover=&quot;true&quot;&gt;
&lt;div class=&quot;c-message_kit__actions c-message_kit__actions--default&quot;&gt;
&lt;div class=&quot;c-message_kit__gutter&quot;&gt;
&lt;div class=&quot;c-message_kit__gutter__right&quot; data-qa=&quot;message_content&quot;&gt;
&lt;div class=&quot;c-message_kit__blocks c-message_kit__blocks--rich_text&quot;&gt;
&lt;div class=&quot;c-message__message_blocks c-message__message_blocks--rich_text&quot; data-qa=&quot;message-text&quot;&gt;
&lt;div class=&quot;p-block_kit_renderer&quot; data-qa=&quot;block-kit-renderer&quot;&gt;
&lt;div class=&quot;p-block_kit_renderer__block_wrapper p-block_kit_renderer__block_wrapper--first&quot;&gt;
&lt;div class=&quot;p-rich_text_block&quot;&gt;
&lt;p style=&quot;line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40);&quot;&gt;Our ranges are established using objective market benchmarking data for this level of work. Final placement within the range is determined by gender-neutral criteria, including the candidate&#39;s relevant skills, experience, and specific qualifications for the role.&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40);&quot;&gt;Actual compensation for this position may vary and will depend on multiple factors such as relevant qualifications, experience, education, and geographic location. For Full-Time Regular Employees, this position is also eligible for additional compensation as follows:&lt;br&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40);&quot;&gt;Sales Roles: This position is eligible for a commission structure in addition to base salary.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 1.5;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: arial, helvetica, sans-serif; color: rgb(40, 40, 40);&quot;&gt;Non-Sales Roles: This position is eligible for an annual bonus which is paid dependent on various factors, including and without limitation, individual and company performance in addition to base salary.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;line-height: 1.5;&quot;&gt;&lt;span style=&quot;color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;&lt;strong&gt;Benefits&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;div style=&quot;line-height: 1.5;&quot;&gt;
&lt;p class=&quot;x_MsoNormal&quot;&gt;&lt;span style=&quot;color: rgb(40, 40, 40); font-size: 12pt;&quot;&gt;G-P values its employees and offers excellent benefits and perks including generous paid parental leave, flexible time off, spending accounts, medical insurance, dental insurance, vision insurance, sabbatical after 5 years and more.&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div style=&quot;line-height: 1.5;&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div style=&quot;line-height: 1.5;&quot;&gt;
