cing&quot;&gt;Reporting into:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; Client Partner&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;br&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;About Ogilvy: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt; &lt;br&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt;Ogilvy UK has been creating iconic ideas that deliver impact at scale for clients ever since David Ogilvy founded the company in 1948. The agency &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt;specialises&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt; in bringing together brand advertising, customer experience marketing, PR, &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt;influence&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt; and consulting, all &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt;fuelled&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt; by &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt;Behavioural&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt; Science.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;br&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt;Ogilvy’s Influencer marketing practice is the largest globally; we are proud to be the most awarded influencer agency for six years running and the recipient of the Cannes Grand Prix for Social &amp;amp; Creator for two consecutive years.  &lt;/span&gt;&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt;Ogilvy UK also hosts the world’s biggest festival of &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt;behavioural&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt; science and creativity, &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt;Nudgestock&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt; – which is now in its 12th year. James Murphy is the CEO of Ogilvy Group UK, which includes Ogilvy UK and New Commercial Arts (NCA), a boutique creative agency he co-founded in 2020, recently &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt;acquired&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt; by WPP. &amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;About this role:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Social and content &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;has&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; never been more important for clients. Showing up authentically, with intention, across social platforms helps brands connect with their audiences. It helps them to sell and serve better.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;This role &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;provides&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; the opportunity to work on &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;a really exciting&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; client&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; within the technology sphere&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;. You will have the opportunity to manage key campaigns across the year that will involve working with our strategy, creative and production team to deliver best in class campaigns and content.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;This role is perfect for someone that has a wide knowledge of social, specifically organic social. They will have experience managing content and campaigns that build brand advocacy as well &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;having an understanding of&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; how to create hard working assets that drive to purchase. The ideal candidate will know how to effectively lead an account, steering &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;processes&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; and ways of working internally, with agency partners and with our clients.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;The ideal candidate will have their finger on the pulse across all things social – from what’s trending that could be a good opportunity for a brand to leverage, through to a thorough understanding of how data, strategy, community management feed into the success of a brands social&lt;/span&gt; &lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;media presence.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Whilst the candidate will have a passion for delivering best in class social campaigns, they will also&lt;/span&gt; &lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;be required&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; to lead in other areas of the marketing mix, and&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; the idea candidate will have some integrated experience.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;A bit about you&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;We are flexible on whether you have come from an agency of client background, but we think the &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;following are &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;really important&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt; for this role:&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;Organised and autonomous; &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;you’ll&lt;/span&gt; &lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;be responsible for&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt; motivating the team to do &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;great work&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;, whilst &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;anticipating&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt; any areas that may hinder the success of the campaign&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
